1	import { writeFileSync } from 'node:fs';
2	import { resolve } from 'node:path';
3	import { ROOT } from './config.js';
4	import { loadConfig } from './config.js';
5	import { launchBrowser, gotoWithRetry } from './browser.js';
6	import { closePopups } from './popups.js';
7	import { log } from './logger.js';
8	
9	/**
10	 * 重度探针：用截图 + 全量响应抓取，看清商品列表页真实状态，定位：
11	 *   1) 列表核心内容有没有渲染（截图直观看）
12	 *   2) 返回商品列表 / 在售数量 / 流量标记的真实接口是哪个（保存 JSON body）
13	 *   3) 列表数据 XHR 是否也被网关重置
14	 *   4) 店铺切换器的真实 DOM
15	 * 产物全部写入 data/probe-*，供离线分析。
16	 */
17	
18	const DIR = resolve(ROOT, 'data');
19	const p = (f) => resolve(DIR, f);
20	
21	const INTEREST = /goods|product|list|page|query|流量|traffic|onSale|在售|skc|sku|mall|shop|seller|item|status|count|summary|filter|tab/i;
22	
23	async function main() {
24	  const cfg = loadConfig();
25	  const { context, page } = await launchBrowser(cfg, { headless: false });
26	
27	  const respLog = [];
28	  let bodyIdx = 0;
29	  const bodyIndex = [];
30	
31	  page.on('response', async (resp) => {
32	    try {
33	      const url = resp.url();
34	      const status = resp.status();
35	      const ct = resp.headers()['content-type'] || '';
36	      let size = -1;
37	      let saved = '';
38	      const isJson = ct.includes('json');
39	      const looksInteresting = INTEREST.test(url);
40	      if (isJson && (looksInteresting || /agentseller\.temu\.com\/(api|bg|visage|drogon|hawk|quick)/.test(url))) {
41	        const text = await resp.text().catch(() => '');
42	        size = text.length;
43	        // 只保存像"业务数据"的：含流量/在售/商品字段，或体积较大
44	        if (/流量|在售|goodsList|productList|itemList|skcId|skuId|totalNum|onSale|pageItems|dataList|salesVolume/i.test(text) || size > 3000) {
45	          const idx = String(++bodyIdx).padStart(2, '0');
46	          const name = `probe-body-${idx}.json`;
47	          writeFileSync(p(name), `// ${resp.request().method()} ${url}\n// status=${status} ct=${ct} size=${size}\n${text.slice(0, 400000)}`, 'utf8');
48	          bodyIndex.push(`${name}  ${resp.request().method()} ${url}  (status=${status}, size=${size})`);
49	          saved = name;
50	        }
51	      }
52	      respLog.push(`${status}  ${resp.request().method()}  ${url}  ct=${ct}  size=${size}  ${saved}`);
53	    } catch { /* ignore */ }
54	  });
55	
56	  page.on('requestfailed', (req) => {
57	    respLog.push(`FAILED  ${req.method()}  ${req.url()}  err=${req.failure()?.errorText || ''}`);
58	  });
59	
60	  const shots = [];
61	  async function shot(tag) {
62	    const name = `probe-${tag}.png`;
63	    await page.screenshot({ path: p(name), fullPage: false }).catch((e) => log.warn(`截图 ${tag} 失败：${e.message}`));
64	    shots.push(name);
65	    log.info(`📸 ${name}`);
66	  }
67	
68	  // 1) 导航
69	  log.info('导航到商品列表页…');
70	  const navOk = await gotoWithRetry(page, cfg.goodsListUrl, cfg, { attempts: 6 });
71	  log.info(`导航结果 navOk=${navOk}，当前 URL=${page.url()}`);
72	  await page.waitForTimeout(3000);
73	  await shot('01-landing');
74	
75	  // 2) 关弹窗
76	  await closePopups(page);
77	  await page.waitForTimeout(1500);
78	  await shot('02-after-popups');
79	
80	  // 3) 若列表未出现，反复：点「商品列表」导航 / reload，直到看到在售中或全部标签
81	  for (let attempt = 1; attempt <= 4; attempt++) {
82	    const hasList = await page
83	      .getByText(/在售中\s*\d|全部\s*\d|待审核|已下架|商品流量/)
84	      .first()
85	      .isVisible({ timeout: 2000 })
86	      .catch(() => false);
87	    log.info(`第 ${attempt} 次检查列表：hasList=${hasList}`);
88	    if (hasList) break;
89	
90	    // 尝试点左侧「商品列表」菜单项
91	    const navItem = page.getByText('商品列表', { exact: true }).first();
92	    if (await navItem.isVisible({ timeout: 1000 }).catch(() => false)) {
93	      log.info('点击左侧「商品列表」菜单…');
94	      await navItem.click({ timeout: 2000 }).catch(() => {});
95	      await page.waitForTimeout(4000);
96	      await closePopups(page);
97	    } else {
98	      log.info('未见「商品列表」菜单项，reload 重试…');
99	      await page.reload({ waitUntil: 'domcontentloaded' }).catch(() => {});
100	      await page.waitForTimeout(4000);
101	      await closePopups(page);
102	    }
103	  }
104	  await shot('03-after-navclick');
105	
106	  // 4) 滚动触发懒加载 + 等接口
107	  await page.mouse.wheel(0, 600).catch(() => {});
108	  await page.waitForTimeout(2500);
109	  await shot('04-final');
110	  writeFileSync(p('probe-final.html'), await page.content().catch(() => ''), 'utf8');
