1	// Service worker：接收接口数据 → 按【店铺名】分别解析/对比/告警。
2	// 多店铺：同一账号下有多个店(HomeCove/Twilight Cove/Agnis)，切到哪个店就记哪个店，各自独立快照与告警。
3	// 数据只存本机 chrome.storage.local，不上传任何服务器。
4	
5	const GOODS_URL = 'https://agentseller.temu.com/goods/list';
6	const DEFAULT_CONFIG = { webhook: '', intervalMinutes: 15, enabled: true, storeName: '' };
7	
8	// ---------------- 解析 ----------------
9	function parseCountStatus(body) {
10	  try {
11	    const j = JSON.parse(body);
12	    const list = j && j.result && j.result.skcTopStatusCountList;
13	    if (!Array.isArray(list)) return null;
14	    const pick = (s) => {
15	      const x = list.find((e) => e && e.skcTopStatus === s);
16	      return x && typeof x.skcTotal === 'number' ? x.skcTotal : null;
17	    };
18	    return { onSale: pick(100), unpublished: pick(0), removed: pick(200), deleted: pick(300) };
19	  } catch (e) { return null; }
20	}
21	function parsePageQuery(body) {
22	  try {
23	    const j = JSON.parse(body);
24	    const r = j && j.result;
25	    if (!r) return null;
26	    return { total: r.total };
27	  } catch (e) { return null; }
28	}
29	
30	// ---------------- 存取 ----------------
31	async function getConfig() {
32	  const { config } = await chrome.storage.local.get('config');
33	  return Object.assign({}, DEFAULT_CONFIG, config || {});
34	}
35	async function getStores() {
36	  const { stores } = await chrome.storage.local.get('stores');
37	  return stores || {};
38	}
39	async function saveStores(stores) {
40	  await chrome.storage.local.set({ stores });
41	}
42	// 更新某店的最新读数
43	async function updateStoreLatest(name, patch) {
44	  const stores = await getStores();
45	  const s = stores[name] || { latest: {}, snapshot: {} };
46	  s.latest = Object.assign({}, s.latest, patch, { ts: Date.now() });
47	  stores[name] = s;
48	  await saveStores(stores);
49	  return s;
50	}
51	
52	// ---------------- 飞书 ----------------
53	async function sendFeishu(webhook, title, lines) {
54	  if (!webhook) return { ok: false, msg: '未配置飞书 webhook' };
55	  const card = {
56	    msg_type: 'interactive',
57	    card: {
58	      header: { title: { tag: 'plain_text', content: title }, template: 'red' },
59	      elements: [{ tag: 'div', text: { tag: 'lark_md', content: lines.join('\n') } }],
60	    },
61	  };
62	  try {
63	    const resp = await fetch(webhook, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(card) });
64	    const data = await resp.json().catch(() => ({}));
65	    const ok = resp.ok && (data.code === 0 || data.StatusCode === 0 || data.code === undefined);
66	    return { ok, msg: ok ? '已发送' : ('飞书返回：' + JSON.stringify(data)) };
67	  } catch (e) {
68	    return { ok: false, msg: '发送失败：' + (e && e.message) };
69	  }
70	}
71	
72	// ---------------- 商品明细 → 带链接的告警行 ----------------
73	// 后台商品操作都是弹窗、无深链，唯一稳定可点的是编辑页（实测格式：SPU ID 即 productId）。
74	function editLink(productId) {
75	  return 'https://agentseller.temu.com/goods/edit?from=productList&productId=' + productId;
76	}
77	// items：当前页可见的限流/下降商品（content.js 扫描 DOM 得到）；total：chip 全量计数。
78	function itemLines(items, total) {
79	  const lines = [];
80	  if (Array.isArray(items) && items.length) {
81	    for (const it of items) {
82	      const nm = String(it.name || '商品').replace(/[[\]]/g, '').slice(0, 30);
83	      lines.push('• [' + nm + '](' + editLink(it.productId) + ')  SKC ' + (it.skc || '-'));
84	    }
85	    if (typeof total === 'number' && total > items.length) {
86	      lines.push('_（本页可见 ' + items.length + ' 条，共 ' + total + ' 条，其余在其它页；点「商品流量待关注」筛选可看全）_');
87	    }
88	  } else if (typeof total === 'number' && total > 0) {
89	    lines.push('_（当前页未显示具体商品，共 ' + total + ' 条；打开「商品流量待关注」筛选可查看）_');
90	  }
91	  return lines;
92	}
93	
94	// ---------------- 对比 & 告警（按店） ----------------
95	async function diffAndAlert(name) {
96	  const cfg = await getConfig();
97	  if (!cfg.enabled) return;
98	  const stores = await getStores();
99	  const s = stores[name];
100	  if (!s) return;
101	  const latest = s.latest || {};
102	  const snap = s.snapshot || {};
103	  const events = [];
104	
105	  // 在售下降不在这里报「只报数字」——改由 diffOnSale 按在售清单 diff 报「具体哪条下架」（带链接），避免同一事件报两次。
106	  if (typeof latest.trafficWatch === 'number' && typeof snap.trafficWatch === 'number' && latest.trafficWatch > snap.trafficWatch) {
107	    events.push(`⚠️ 商品流量待关注增加：${snap.trafficWatch} → ${latest.trafficWatch}`);
108	    events.push(...itemLines(latest.watchItems, latest.trafficWatch));
109	  }
110	  // 「商品流量近期有下降」商品数增加（相对已建立的基准，首次不报）
111	  if (typeof latest.trafficDecline === 'number' && typeof snap.trafficDecline === 'number' && latest.trafficDecline > snap.trafficDecline) {
112	    events.push(`🔴 商品流量近期有下降增加：${snap.trafficDecline} → ${latest.trafficDecline}（本页可见）`);
113	    events.push(...itemLines(latest.declineItems, null));
114	  }
115	
116	  if (events.length > 0) {
117	    const lines = [`**🏬 ${name}**`, ...events, '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
118	    const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
119	    await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
120	  }
121	
122	  // 合并式更新该店基准快照（只覆盖本次拿到的数值），幂等只报一次
123	  const newSnap = Object.assign({}, snap);
124	  if (typeof latest.onSale === 'number') newSnap.onSale = latest.onSale;
125	  if (typeof latest.total === 'number') newSnap.total = latest.total;
126	  if (typeof latest.trafficWatch === 'number') newSnap.trafficWatch = latest.trafficWatch;
127	  if (typeof latest.trafficDecline === 'number') newSnap.trafficDecline = latest.trafficDecline;
128	  newSnap.ts = Date.now();
129	  s.snapshot = newSnap;
130	  stores[name] = s;
131	  await saveStores(stores);
132	}
133	
134	// 在售清单 diff：找出「上一轮在售、这一轮不在」的商品 = 下架/移出在售，带商品名+编辑链接告警。
135	// items 为 content.js 扫「在售中」tab 得到的当前在售商品(productId+name+skc)。返回下架数量(供日志)。
136	async function diffOnSale(name, items) {
137	  if (!Array.isArray(items) || !items.length) return 0; // 空 = 扫描失败或真 0，稳妥起见不动基准、不报
138	  const cfg = await getConfig();
139	  const stores = await getStores();
140	  const s = stores[name] || { latest: {}, snapshot: {} };
141	  // 防残缺扫描误判：已知在售数(countStatus)时，扫到的必须不少于它，否则视为没扫全 → 跳过
142	  const known = s.latest && typeof s.latest.onSale === 'number' ? s.latest.onSale : null;
143	  if (known != null && items.length < known) return 0;
144	  const newMap = {};
145	  for (const it of items) if (it && it.productId) newMap[it.productId] = { name: it.name || '', skc: it.skc || '' };
146	  const prevMap = s.snapshot && s.snapshot.onSaleIds;
147	  let delistedCount = 0;
148	  if (prevMap && cfg.enabled) { // 首次无基准 → 只记录不报
149	    const delisted = Object.keys(prevMap).filter((pid) => !(pid in newMap));
150	    delistedCount = delisted.length;
151	    if (delisted.length) {
152	      const its = delisted.map((pid) => ({ productId: pid, name: prevMap[pid].name, skc: prevMap[pid].skc }));
153	      const lines = [`**🏬 ${name}**`, `📉 在售商品下架 ${delisted.length} 个（在售 ${Object.keys(prevMap).length} → ${items.length}）:`,
154	        ...itemLines(its, null), '', `_检查时间：${new Date().toLocaleString('zh-CN')}_`];
155	      const r = await sendFeishu(cfg.webhook, '🔔 Temu 店铺监测告警', lines);
156	      await chrome.storage.local.set({ lastAlert: { ts: Date.now(), ok: r.ok, msg: r.msg, store: name, lines } });
157	    }
158	  }
159	  s.snapshot = Object.assign({}, s.snapshot, { onSaleIds: newMap, onSaleIdsTs: Date.now() });
160	  stores[name] = s;
161	  await saveStores(stores);
162	  return delistedCount;
163	}
164	
165	// 解析店铺名：优先用页面读到的店名；读不到则退回配置里手填的，再退回“当前店铺”
166	async function resolveStore(msgStore) {
167	  if (msgStore && String(msgStore).trim()) return String(msgStore).trim();
168	  const cfg = await getConfig();
169	  return (cfg.storeName && cfg.storeName.trim()) || '当前店铺';
170	}
171	
172	// ---------------- 消息处理 ----------------
173	chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
174	  (async () => {
175	    if (msg.type === 'capture') {
176	      const name = await resolveStore(msg.store);
177	      if (msg.kind === 'countStatus') {
178	        const p = parseCountStatus(msg.body);
179	        if (p && p.onSale != null) {
180	          await updateStoreLatest(name, { onSale: p.onSale, unpublished: p.unpublished, removed: p.removed, deleted: p.deleted });
181	          await diffAndAlert(name);
182	        }
183	      } else if (msg.kind === 'pageQuery') {
184	        const p = parsePageQuery(msg.body);
185	        if (p) await updateStoreLatest(name, { total: p.total });
186	      }
187	      sendResponse({ ok: true });
188	      return;
189	    }
190	    if (msg.type === 'chipStats') {
191	      const patch = {};
192	      if (typeof msg.trafficWatch === 'number') patch.trafficWatch = msg.trafficWatch;
193	      if (typeof msg.trafficDecline === 'number') patch.trafficDecline = msg.trafficDecline;
194	      if (Array.isArray(msg.watchItems)) patch.watchItems = msg.watchItems;
195	      if (Array.isArray(msg.declineItems)) patch.declineItems = msg.declineItems;
196	      if (Object.keys(patch).length) {
197	        const name = await resolveStore(msg.store);
198	        await updateStoreLatest(name, patch);
199	        await diffAndAlert(name);
200	      }
201	      sendResponse({ ok: true });
202	      return;
203	    }
204	    if (msg.type === 'getStatus') {
205	      sendResponse({ bgVersion: 'v3-下架点名', config: await getConfig(), stores: await getStores(), ...(await chrome.storage.local.get(['lastAlert', 'lastCycle'])) });
206	      return;
207	    }
208	    if (msg.type === 'addStore') {
209	      const name = (msg.name || '').trim();
210	      if (!name) { sendResponse({ ok: false, msg: '店铺名不能为空' }); return; }
211	      const stores = await getStores();
212	      if (stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」已存在' }); return; }
213	      stores[name] = { latest: {}, snapshot: {} };
214	      await saveStores(stores);
215	      sendResponse({ ok: true, msg: '已添加「' + name + '」，下次轮巡将尝试切到该店抓数' });
216	      return;
217	    }
218	    if (msg.type === 'deleteStore') {
219	      const name = (msg.name || '').trim();
220	      const stores = await getStores();
221	      if (!stores[name]) { sendResponse({ ok: false, msg: '「' + name + '」不存在' }); return; }
222	      delete stores[name];
223	      await saveStores(stores);
224	      sendResponse({ ok: true, msg: '已删除「' + name + '」' });
225	      return;
226	    }
227	    if (msg.type === 'checkNow') {
228	      sendResponse(await pollNow());
229	      return;
230	    }
231	    if (msg.type === 'cycleNow') {
232	      sendResponse(await cycleStores('manual'));
233	      return;
234	    }
235	    if (msg.type === 'testFeishu') {
236	      const cfg = await getConfig();
237	      const r = await sendFeishu(cfg.webhook, '✅ Temu 监测测试', ['这是一条测试消息，收到说明飞书配置正常。', '', `_${new Date().toLocaleString('zh-CN')}_`]);
238	      sendResponse(r);
239	      return;
240	    }
241	  })();
242	  return true;
243	});
244	
245	// ---------------- 自动轮巡（切遍每个店抓数，再切回原店；仅空闲时触发） ----------------
246	const IDLE_SECONDS = 240; // 无操作 4 分钟视为空闲
247	let cycling = false;
248	
249	async function getGoodsTab() {
250	  const tabs = await chrome.tabs.query({ url: 'https://agentseller.temu.com/*' });
251	  return tabs.find((t) => /goods\/list/.test(t.url || '')) || tabs[0] || null;
252	}
253	function sendTab(tabId, cmd) {
254	  return new Promise((resolve) => {
255	    try {
256	      chrome.tabs.sendMessage(tabId, cmd, (resp) => {
257	        if (chrome.runtime.lastError) resolve(null); else resolve(resp);
258	      });
259	    } catch (e) { resolve(null); }
260	  });
261	}
262	async function sendTabRetry(tabId, cmd, tries) {
263	  for (let i = 0; i < (tries || 8); i++) {
264	    const r = await sendTab(tabId, cmd);
265	    if (r) return r;
266	    await new Promise((res) => setTimeout(res, 1000)); // 页面重载后 content 未就绪，重试
267	  }
268	  return null;
269	}
270	function sleep(ms) { return new Promise((r) => setTimeout(r, ms)); }
271	// 等某店在切换后被重新抓到（latest.ts 比切换前更新、且有 onSale）
272	async function waitForStoreCapture(name, sinceTs, timeout) {
273	  const t0 = Date.now();
274	  while (Date.now() - t0 < (timeout || 25000)) {
275	    const stores = await getStores();
276	    const L = stores[name] && stores[name].latest;
277	    if (L && typeof L.onSale === 'number' && (L.ts || 0) > sinceTs) return true;
278	    await sleep(1500);
279	  }
280	  return false;
281	}
282	
283	async function cycleStores(reason) {
284	  if (cycling) return { ok: false, msg: '轮巡进行中' };
285	  cycling = true;
286	  const log = [];
287	  try {
288	    const tab = await getGoodsTab();
289	    if (!tab) return { ok: false, msg: '没有打开的 Temu 商品页' };
290	    const cur = await sendTabRetry(tab.id, { cmd: 'ping' }, 5);
291	    const original = cur && cur.store;
292	    log.push('当前店：' + (original || '未知'));
293	
294	    // 店铺清单：优先用“已知店”（之前逛各店时按顶栏店名记下的，干净准确）；
295	    // 不足 2 个才去弹窗探测（探测会混入页面杂项英文，仅作兜底）。
296	    const known = Object.keys(await getStores()).filter((n) => n && n !== '当前店铺');
297	    let names;
298	    if (known.length >= 2) {
299	      names = known;
300	      log.push('店铺(已知)：' + names.join(', '));
301	    } else {
302	      const listed = await sendTabRetry(tab.id, { cmd: 'listStores' }, 5);
303	      names = [...new Set([...((listed && listed.names) || []), ...known])].filter(Boolean);
304	      log.push('店铺(探测)：' + names.join(', '));
305	    }
306	    if (names.length === 0) return { ok: false, msg: '没识别到店铺清单' };
307	
308	    for (const name of names) {
309	      if (name === original) continue; // 原店最后再确认；先切别的
310	      const since = Date.now();
311	      const r = await sendTabRetry(tab.id, { cmd: 'switchTo', target: name }, 5);
312	      if (!r || !r.ok) { log.push('切到 ' + name + ' 失败：' + (r && r.msg)); continue; }
313	      const got = await waitForStoreCapture(name, since, 25000);
314	      log.push((got ? '✓ ' : '✗ ') + name);
315	      // 扫在售清单 → diff 出下架商品（带链接告警）
316	      if (got) {
317	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
318	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(name, os.items); if (d) log.push('  ↳下架' + d + '个'); }
319	      }
320	    }
321	    // 切回原店
322	    if (original) {
323	      const since = Date.now();
324	      await sendTabRetry(tab.id, { cmd: 'switchTo', target: original }, 5);
325	      const gotBack = await waitForStoreCapture(original, since, 25000);
326	      if (gotBack) {
327	        const os = await sendTabRetry(tab.id, { cmd: 'scanOnSale' }, 3);
328	        if (os && Array.isArray(os.items)) { const d = await diffOnSale(original, os.items); if (d) log.push('  ↳' + original + '下架' + d + '个'); }
329	      }
330	      log.push('已切回 ' + original);
331	    }
332	    const summary = log.join(' | ');
333	    await chrome.storage.local.set({ lastCycle: { ts: Date.now(), reason, summary } });
334	    return { ok: true, msg: summary };
335	  } finally { cycling = false; }
336	}
337	
338	async function pollNow() {
339	  const tab = await getGoodsTab();
340	  if (!tab) return { ok: false, msg: '未找到打开的 Temu 后台标签页，请先登录并打开商品列表页' };
341	  if (/goods\/list/.test(tab.url || '')) { await chrome.tabs.reload(tab.id, { bypassCache: false }); return { ok: true, msg: '已刷新后台商品页' }; }
342	  await chrome.tabs.update(tab.id, { url: GOODS_URL });
343	  return { ok: true, msg: '已导航到商品列表页' };
344	}
345	
346	// 定时：空闲则轮巡所有店，否则不打扰（靠随看随记覆盖当前店）
347	chrome.alarms.onAlarm.addListener((a) => {
348	  if (a.name !== 'poll') return;
349	  chrome.idle.queryState(IDLE_SECONDS, (state) => {
350	    if (state === 'idle' || state === 'locked') cycleStores('idle');
351	  });
352	});
353	
354	async function setupAlarm() {
355	  await chrome.storage.local.remove('trafficSample'); // 清早期诊断残留
356	  const cfg = await getConfig();
357	  await chrome.alarms.clear('poll');
358	  chrome.alarms.create('poll', { periodInMinutes: Math.max(1, cfg.intervalMinutes || 15) });
359	}
360	chrome.runtime.onInstalled.addListener(setupAlarm);
361	chrome.runtime.onStartup.addListener(setupAlarm);
362	chrome.storage.onChanged.addListener((changes, area) => { if (area === 'local' && changes.config) setupAlarm(); });
