233	      diag.push('模态计数 切换店铺=' + textEls(/切换店铺/, 20).length + ' 您的账户=' + textEls(/您的账户/, 40).length);
234	    }
235	    return ok;
236	  }
237	
238	  async function listStores() {
239	    if (!(await openStoreModal())) return [];
240	    await sleep(500);
241	    // 每个店铺行都带“半托管/全托管”标签；据此定位店名，避开背景页面的杂项英文
242	    const tags = textEls(/托管/, 6).filter(visible);
243	    const names = [];
244	    for (const tag of tags) {
245	      let row = tag.parentElement;
246	      for (let i = 0; i < 4 && row; i++) {
247	        const en = [...row.querySelectorAll('span,div,p,a')]
248	          .map((e) => (e.textContent || '').trim())
249	          .find((t) => /^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t) && t.length >= 2 && t.length <= 30 && !/^(NEW|Beta)$/i.test(t));
250	        if (en) { names.push(en); break; }
251	        row = row.parentElement;
252	      }
253	    }
254	    closeModal();
255	    const uniq = [...new Set(names)];
256	    LOG('listStores =>', uniq);
257	    return uniq;
258	  }
259	
260	  async function switchTo(target) {
261	    const diag = [];
262	    if (!(await openStoreModal(diag))) return { ok: false, msg: '打不开弹窗 | ' + diag.join(' ; ') };
263	    await sleep(300);
264	    const esc = String(target).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
265	    const rows = textEls(new RegExp(esc), 120).filter((e) => /切换/.test(e.textContent || ''));
266	    const row = innermost(rows);
267	    if (!row) { closeModal(); return { ok: false, msg: '弹窗里没找到店铺 ' + target }; }
268	    let btn = [...row.querySelectorAll('button,[role=button]')].find((b) => /切换/.test(b.textContent || '') && !b.disabled && b.getAttribute('aria-disabled') !== 'true');
269	    if (!btn) {
270	      const cands = textEls(/^切换$/, 6).map(clickableAncestor).filter((b) => b && !b.disabled);
271	      btn = cands.find((b) => row.contains(b) || (b.compareDocumentPosition(row) & Node.DOCUMENT_POSITION_CONTAINED_BY)) || null;
272	    }
273	    if (!btn) { closeModal(); return { ok: false, msg: '没找到可点的切换按钮(' + target + ')，可能已是当前店' }; }
274	    LOG('switchTo click', target);
275	    realClick(btn); // 触发切店（SPA 更新或整页重载）
276	    return { ok: true, msg: '已点击切换到 ' + target };
277	  }
278	
279	  // 扫「在售中」商品清单：点在售 tab → 等在售网格 → scanProducts 取 productId+name+skc。
280	  // 用于 background diff 出"上轮在售、这轮不在"的下架商品。仅轮巡(空闲)时调，扫完点回「全部」。
281	  async function scanOnSaleList() {
282	    const findTab = (re) => {
283	      const labels = [...document.querySelectorAll('[data-testid="beast-core-tab-itemLabel"]')].filter(visible);
284	      return labels.find((e) => re.test((e.textContent || '').trim())) || textEls(re, 14).filter(visible)[0] || null;
285	    };
286	    const onSaleTab = findTab(/^在售中/);
287	    if (onSaleTab) realClick(clickableAncestor(onSaleTab));
288	    await waitFor(() => document.querySelector('[data-testid="beast-core-table-body-tr"]'), 8000, 300);
289	    await sleep(1800); // 等在售网格稳定渲染（避免只扫到半页）
290	    const products = scanProducts();
291	    const items = products.map((p) => ({ productId: p.productId, name: p.name, skc: p.skc }));
292	    // 恢复到「全部」tab（轮巡时用户看不到，但保持视图干净）
293	    const allTab = findTab(/^全部/);
294	    if (allTab) realClick(clickableAncestor(allTab));
295	    return { store: readStoreName(), items: items };
296	  }
297	
298	  chrome.runtime.onMessage.addListener((msg, sender, sendResponse) => {
299	    if (!msg || !msg.cmd) return;
300	    (async () => {
301	      try {
302	        if (msg.cmd === 'ping') { sendResponse({ store: readStoreName() }); return; }
303	        if (msg.cmd === 'listStores') { sendResponse({ names: await listStores() }); return; }
304	        if (msg.cmd === 'switchTo') { sendResponse(await switchTo(msg.target)); return; }
305	        if (msg.cmd === 'scanOnSale') { sendResponse(await scanOnSaleList()); return; }
306	      } catch (e) { sendResponse({ ok: false, msg: String((e && e.message) || e) }); }
307	    })();
308	    return true;
